export const GROWTH_REF: Record<string, GrowthTable> = {
  height: GROWTH_HEIGHT,
  weight: GROWTH_WEIGHT,
  headCircumference: GROWTH_HEAD,
};

export function getPercentileBand(
  table: GrowthTable,
  gender: GenderKey,
  month: number,
  value: number,
): string {
  const row = table[gender]?.[Math.round(month)];
  if (!row) return '';
  const labels = ['3백분위 미만', '3~10', '10~25', '25~75', '75~90', '90~97', '97백분위 이상'];
  if (value < row[0]) return labels[0];
  if (value >= row[6]) return labels[6];
  const idx = row.findIndex((p, i) => i < 6 && value >= p && value < row[i + 1]);
  return idx >= 0 ? labels[idx + 1] : '';
}
